:root {
  --bg: #0d1117;
  --panel: #161b22;
  --panel2: #1c2330;
  --line: #2a3342;
  --text: #e6edf3;
  --muted: #8b949e;
  --accent: #58a6ff;
  --good: #3fb950;
  --warn: #d29922;
  --bad: #f85149;
  --bar: #1f6feb;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font: 15px/1.55 system-ui, -apple-system, "Segoe UI", sans-serif;
}
header {
  display: flex;
  flex-wrap: wrap;
  gap: 16px 32px;
  justify-content: space-between;
  align-items: end;
  padding: 28px 24px 20px;
  border-bottom: 1px solid var(--line);
}
h1 { margin: 0 0 6px; font-size: 30px; letter-spacing: -0.5px; }
.lede { margin: 0; color: var(--muted); max-width: 640px; }
.stats { display: flex; gap: 24px; margin: 0; flex-wrap: wrap; }
.stats div { min-width: 84px; }
.stats dt { color: var(--muted); font-size: 12px; text-transform: uppercase; letter-spacing: 0.06em; }
.stats dd { margin: 2px 0 0; font-size: 22px; font-weight: 650; }
main { max-width: 1080px; margin: 0 auto; padding: 20px 24px 40px; }
section { margin-bottom: 28px; }
h2 { font-size: 18px; margin: 0 0 10px; }
h3 { font-size: 15px; margin: 0 0 6px; }
.picks { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 12px; }
.pick {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 12px 14px;
  cursor: pointer;
}
.pick:hover { border-color: var(--accent); }
