.controls label { color: var(--muted); font-size: 13px; display: grid; gap: 4px; }
.controls input, .controls select {
  background: var(--panel);
  color: var(--text);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 7px 10px;
  font: inherit;
}
.tabs { display: flex; gap: 6px; margin-left: auto; }
.tabs button {
  background: var(--panel);
  color: var(--muted);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 7px 12px;
  font: inherit;
  cursor: pointer;
}
.tabs button[aria-selected="true"] { background: var(--panel2); color: var(--text); border-color: var(--accent); }
table { width: 100%; border-collapse: collapse; font-size: 14px; }
th, td { padding: 8px 10px; border-bottom: 1px solid var(--line); text-align: left; }
th { color: var(--muted); font-size: 12px; text-transform: uppercase; letter-spacing: 0.05em; cursor: pointer; user-select: none; }
th.num, td.num { text-align: right; font-variant-numeric: tabular-nums; }
tbody tr { cursor: pointer; }
tbody tr:hover { background: var(--panel); }
.flag { display: inline-block; background: #3a2b00; color: #f0b429; border: 1px solid #6b4d00; border-radius: 4px; padding: 0 6px; font-size: 12px; margin: 1px 2px 1px 0; }
.flag.none { background: transparent; color: var(--muted); border-color: var(--line); }
.mini-bar { height: 6px; background: var(--panel); border-radius: 3px; margin-top: 4px; overflow: hidden; }
.mini-bar i { display: block; height: 100%; background: var(--bar); }
.note { color: var(--muted); font-size: 13px; }
dialog {
  background: var(--panel);
  color: var(--text);
  border: 1px solid var(--line);
  border-radius: 12px;
  max-width: 620px;
  width: calc(100% - 40px);
  padding: 20px 22px;
}
dialog::backdrop { background: rgba(0, 0, 0, 0.6); }
dialog h2 { margin-top: 0; }
dialog .close { float: right; background: none; border: 1px solid var(--line); color: var(--muted); border-radius: 6px; padding: 4px 10px; cursor: pointer; }
dialog dl { display: grid; grid-template-columns: 170px 1fr; gap: 4px 12px; font-size: 14px; }
dialog dt { color: var(--muted); }
dialog dd { margin: 0; }
dialog ol { padding-left: 20px; }
dialog li { margin-bottom: 8px; }
.model { background: var(--panel); border: 1px solid var(--line); border-radius: 10px; padding: 16px 18px; }
.model code { background: var(--panel2); padding: 1px 6px; border-radius: 4px; }
@media (max-width: 640px) {
  .bar-row { grid-template-columns: 110px 1fr 70px; }
  dialog dl { grid-template-columns: 1fr; }
}
